arguments.command:
cat << 'EOF' > /tmp/bconv.sh
#!/bin/bash
echo -e "══ QUICK UNIT CONVERTER ══\r\n1) Celsius to Fahrenheit\r\n2) Kilometers to Miles\r\n3) Kilograms to Pounds\r"
read -p "Choose option (1-3): " opt
read -p "Enter value to convert: " val
if ! [[ "$val" =~ ^[0-9.]+$ ]]; then echo -e "Invalid number!\r"; exit 1; fi
case "$opt" in
  1) res=$(echo "scale=2; ($val * 9/5) + 32" | bc); echo -e "$val °C = $res °F\r" ;;
  2) res=$(echo "scale=2; $val * 0.621371" | bc); echo -e "$val Km = $res Miles\r" ;;
  3) res=$(echo "scale=2; $val * 2.20462" | bc); echo -e "$val Kg = $res Lbs\r" ;;
  *) echo -e "Invalid option\r" ;;
esac
EOF
tput cuu 1 && termy_say "Opening unit converter" > /dev/null 2>&1 && printf "\r\n" && bash /tmp/bconv.sh; rm -f /tmp/bconv.sh && printf ""

cat << 'EOF' > /tmp/btodo.sh
#!/bin/bash
FILE="$HOME/.bash_todos"; touch "$FILE"; clear
echo -e "═══ CLI TODO MANAGER ═══\r\n1) List Tasks | 2) Add Task | 3) Remove Task | 4) Quit\r"
while :; do
  read -p "todo> " opt
  case "$opt" in
    1) clear; echo -e "══ Current Tasks ══\r"; if [ ! -s "$FILE" ]; then echo -e "(No tasks found)\r"; else nl -w2 -s') ' "$FILE"; fi; echo -e "\r" ;;
    2) read -p "Enter new task: " task; [ -n "$task" ] && echo "$task" >> "$FILE" && echo -e "Task added! \r" ;;
    3) clear; echo -e "══ Remove Task ══\r"; nl -w2 -s') ' "$FILE"; read -p "Enter task number to delete: " num
       if [[ "$num" =~ ^[0-9]+$ ]]; then sed -i "${num}d" "$FILE" && echo -e "Task removed! \r"; else echo -e "Invalid number\r"; fi ;;
    4) break ;;
    *) echo -e "Options: 1 (List), 2 (Add), 3 (Remove), 4 (Quit)\r" ;;
  esac
done
EOF
tput cuu 1 && termy_say "Starting to do manager" > /dev/null 2>&1 && printf "\r\n" && bash /tmp/btodo.sh && rm -f /tmp/btodo.sh && printf ""
